  8	  var nelems: int;
  9	
 10	  ghost var Repr : set<object>
 11	  ghost var elems : set<int>
 12	
 13	
 14	  ghost predicate RepInv()
 15	    reads this, Repr
 16	  {
 17	    this in Repr && store in Repr &&
 18	    0 < store.Length
 19	    && 0 <= nelems <= store.Length
 20	    && (forall i :: 0 <= i < nelems ==> store[i] in elems)
 21	    && (forall x :: x in elems ==> exists i :: 0 <= i < nelems && store[i] == x)
 22	  }
 23	  // the construction operation
 24	  constructor(n: int)
 25	    requires 0 < n
 26	    ensures RepInv()
 27	    ensures fresh(Repr-{this})
 28	  {
 29	    store := new int[n];
 30	    Repr := {this,store};
 31	    elems := {};
 32	    nelems := 0;
 33	  }
 34	  // returns the number of elements in the set
 35	  function size():int
 36	    requires RepInv()
 37	    ensures RepInv()
 38	    reads Repr
 39	  { nelems }
 40	  // returns the maximum number of elements in the set
 41	  function maxSize():int
 42	    requires RepInv()
 43	    ensures RepInv()
 44	    reads Repr
 45	  { store.Length }
 46	  // checks if the element given is in the set
 47	  method contains(v:int) returns (b:bool)
 48	    requires RepInv()
 49	    ensures RepInv()
 50	    ensures b <==> v in elems
 51	  {
 52	
 53	    var i := find(v);
 54	    return i >= 0;
 55	  }
 56	  // adds a new element to the set if space available
 57	
 58	  method add(v:int)
 59	    requires RepInv()
 60	    requires size() < maxSize()
 61	    ensures RepInv()
 62	    modifies this,Repr
 63	    ensures fresh(Repr - old(Repr))
 64	  {
 65	    var f:int := find(v);
 66	    if (f < 0) {
 67	      store[nelems] := v;
 68	      elems := elems + {v};
 69	      assert forall i:: 0 <= i < nelems ==> old(store[i]) == store[i];
 70	      nelems := nelems + 1;
 71	    }
 72	  }
 73	  // private method that should not be in the
 74	  method find(x:int) returns (r:int)
 75	    requires RepInv()
 76	    ensures RepInv()
 77	    ensures r < 0 ==> x !in elems
 78	    ensures r >=0 ==> x in elems;
 79	  {
 80	    var i:int := 0;
 81	    while (i<nelems)
 82	      decreases nelems-i
 83	      invariant 0 <= i <= nelems;
 84	      invariant forall j::(0<=j< i) ==> x != store[j];
 85	    {
 86	      if (store[i]==x) { return i; }
 87	      i := i + 1;
 88	    }
 89	    return -1;
 90	  }
 91	  method Main()
 92	  {
 93	    var s := new Set(10);
 94	    if (s.size() < s.maxSize()) {
 95	      s.add(2);
 96	      var b := s.contains(2);
 97	      if (s.size() < s.maxSize()) {
 98	        s.add(3);
 99	      }
100	    }
101	  }
102	}
